 * Damage-coverage rate per category (fraction of the subtotal).
 */
export const COVERAGE_RATES: Record<CategoryId, number> = {
  "fotografia-video": 0.2,
  "montana-camping": 0.1,
  "deportes-acuaticos": 0.1,
};

/**
 * Calculate rental price breakdown.
 * Works in integer cents; coverage is rounded to the cent, halves up.
 * Without a category no coverage is applied.
 */
export function calculateRentalPrice(
  dailyRate: number,
  startDate: Date,
  endDate: Date,
  category?: CategoryId
): {
  days: number;
  dailyRate: number;
  subtotal: number;
  coverageRate: number;
  coverageFee: number;
  total: number;
} {
  const days = calculateRentalDays(startDate, endDate);
  const subtotalCents = Math.round(dailyRate * 100) * days;
  const coverageRate = category ? COVERAGE_RATES[category] : 0;
  // rate as integer percent to avoid float error (0.2 * 100 = 20)
  const ratePercent = Math.round(coverageRate * 100);
  const coverageCents = Math.floor((subtotalCents * ratePercent + 50) / 100);

  return {
    days,
    dailyRate,
    subtotal: subtotalCents / 100,
    coverageRate,
    coverageFee: coverageCents / 100,
    total: (subtotalCents + coverageCents) / 100,
  };
}

/**
 * Format price in Mexican Pesos (two decimals)
 */
export function formatPrice(amount: number): string {
  return new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
}

